<?php
$stats = [ 'Inventory items'=>query('SELECT COUNT(*) FROM items')->fetchColumn(), 'Available units'=>query('SELECT COALESCE(SUM(quantity),0) FROM items')->fetchColumn(), 'Active borrowings'=>query("SELECT COUNT(*) FROM borrowings WHERE status='borrowed'")->fetchColumn(), 'Low-stock items'=>query('SELECT COUNT(*) FROM items WHERE quantity<=low_stock')->fetchColumn() ];
?><div class="stats"><?php foreach($stats as $label=>$value): ?><article class="panel"><span><?= e($label) ?></span><strong><?= e($value) ?></strong></article><?php endforeach ?></div>
<div class="columns"><section class="panel"><h2>Stock needs attention</h2><p>Items at or below their restock threshold.</p><table><tr><th>Item</th><th>Available</th><th>Location</th></tr><?php $rows=query('SELECT * FROM items WHERE quantity<=low_stock ORDER BY quantity LIMIT 10')->fetchAll(); foreach($rows as $r): ?><tr><td><?= e($r['name']) ?></td><td><span class="badge warn"><?= e($r['quantity'].' '.$r['unit']) ?></span></td><td><?= e($r['location']) ?></td></tr><?php endforeach ?></table><?php if(!$rows): ?><p class="empty">All stocked up. No low-stock alerts.</p><?php endif ?><a href="?page=inventory">View inventory →</a></section><section class="panel"><h2>Overdue returns</h2><?php $sql="SELECT b.*,i.name FROM borrowings b JOIN items i ON i.id=b.item_id WHERE b.status='borrowed' AND b.due_date<CURDATE()"; $rows=query($sql.(!manager()?' AND b.user_id=?':''),!manager()?[$me['id']]:[])->fetchAll(); foreach($rows as $r): ?><p><b><?= e($r['name']) ?></b><br>Due <?= e($r['due_date']) ?></p><?php endforeach; if(!$rows): ?><p class="empty">No overdue returns.</p><?php endif ?><a href="?page=borrowing">Manage borrowing →</a></section></div>
